-- Platform administration (ADR 0015): a Super Admin lists organizations across tenants. Identifiers and a count
-- only; the service loads each organization inside withTenant(). Who may call this is decided by the service's
-- SuperAdminGuard (role looked up in the identity service on every request), like every other definer function.
CREATE FUNCTION platform_organization_ids(p_limit integer, p_before uuid)
RETURNS TABLE (organization_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  SELECT o.id
  FROM organization.organizations o
  WHERE o.deleted_at IS NULL
    AND (p_before IS NULL OR o.id < p_before)
  ORDER BY o.id DESC
  LIMIT least(greatest(coalesce(p_limit, 1), 1), 101); -- a page of at most 100, plus one to detect the next page
$$;

CREATE FUNCTION platform_organization_count()
RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  SELECT count(*) FROM organization.organizations o WHERE o.deleted_at IS NULL;
$$;

COMMIT;
